// Initialize dynamic relations (e.g. easyToMissRules from rules array)
// Firms without clause-level rules get honest parameter-derived rules (INFERENCE
// evidence, clause citation pending) so no dossier page ever renders empty.
PROP_FIRMS_DATA.forEach((firm) => {
  if (firm.rules.length === 0) {
    try {
      firm.rules = buildParameterRules(firm);
    } catch {
      // Leave empty if the firm has no accounts to derive from
    }
  }
  firm.easyToMissRules = firm.rules.filter((r) => r.isEasyToMiss);
  firm.programs.forEach((prog) => {
    prog.accounts.forEach((acc) => {
      acc.rules = firm.rules;
    });
  });
});

